### Description
This Terraform program sets up a basic infrastructure on AWS, including a Virtual Private Cloud (VPC), a subnet, an Elastic Load Balancer (ELB), a Route 53 hosted zone, and a Route 53 record that points to the ELB. The dependencies between these resources are managed to ensure proper creation order.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "main_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_elb" "main_elb" {
  name               = "main-elb"
  subnets            = [aws_subnet.main_subnet.id]
  security_groups    = ["sg-00000000000000000"]  # Replace with a valid security group ID
  internal           = false
  cross_zone_load_balancing = true

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }
}

resource "aws_route53_zone" "primary_zone" {
  name = "example.com"
  vpc {
    vpc_id = aws_vpc.main_vpc.id
  }
}

resource "aws_route53_record" "www_record" {
  name    = "www"
  zone_id = aws_route53_zone.primary_zone.zone_id
  type    = "A"

  alias {
    name                   = aws_elb.main_elb.dns_name
    zone_id                = aws_elb.main_elb.zone_id
    evaluate_target_health = true
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Subnet**: A subnet is created within the VPC with a CIDR block of `10.0.1.0/24` and placed in the `us-west-2a` availability zone.
- **Elastic Load Balancer (ELB)**: An ELB is set up with a listener on port 80 using HTTP. The health check is configured to monitor the HTTP endpoint on port 80.
- **Route 53 Zone**: A Route 53 hosted zone is created for the domain `example.com` and associated with the VPC.
- **Route 53 Record**: A Route 53 record named `www` is created to point to the ELB using an alias record, which ensures low latency and high availability.

Make sure to replace `"sg-00000000000000000"` with a valid security group ID in your AWS account.

