### Description
This Terraform program sets up a Blue/Green deployment using AWS Elastic Beanstalk and Route53. It creates two Elastic Beanstalk environments named "blue" and "green", and configures Route53 records with a Weighted Routing Policy to manage traffic between these environments.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_elastic_beanstalk_application" "my_app" {
  name = "my-app"
}

resource "aws_elastic_beanstalk_environment" "blue_env" {
  name                = "blue-env"
  application         = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
}

resource "aws_elastic_beanstalk_environment" "green_env" {
  name                = "green-env"
  application         = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
}

resource "aws_route53_zone" "my_domain" {
  name = "example.com"
}

resource "aws_route53_record" "blue_record" {
  name    = "www.example.com"
  type    = "A"
  zone_id = aws_route53_zone.my_domain.zone_id

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.blue_env.cname
    zone_id                = aws_elastic_beanstalk_environment.blue_env.endpoint_url
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "green_record" {
  name    = "www.example.com"
  type    = "A"
  zone_id = aws_route53_zone.my_domain.zone_id

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.green_env.cname
    zone_id                = aws_elastic_beanstalk_environment.green_env.endpoint_url
    evaluate_target_health = true
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Elastic Beanstalk Application**: An Elastic Beanstalk application named "my-app" is created.
- **Elastic Beanstalk Environments**: Two environments, "blue-env" and "green-env", are created under the "my-app" application. Both environments use the same solution stack.
- **Route53 Zone**: A Route53 zone for the domain "example.com" is created.
- **Route53 Records**: Two weighted Route53 records are created for "www.example.com". Each record points to one of the Elastic Beanstalk environments with a weight of 50, allowing equal traffic distribution between the blue and green environments.

