### Description

This Terraform program sets up a blue/green deployment with Route 53 resources to direct traffic to two separate environments that are connected to a shared RDS database. It includes the following components:

1. **AWS Provider Configuration**: Configures the AWS provider with a specific region.
2. **IAM Role**: Creates an IAM role named `eb_ec2_profile`.
3. **VPC and Subnets**: Sets up VPCs and subnets for the blue and green environments.
4. **Security Group**: Creates a security group for the RDS instances.
5. **RDS Database Instances**: Deploys a primary RDS database and two replicated instances for the blue and green environments.
6. **DB Proxy**: Sets up a DB proxy to manage connections to the RDS instances.
7. **Route 53 Hosted Zone**: Creates a Route 53 hosted zone for DNS management.
8. **Route 53 Records**: Configures Route 53 records for the blue and green environments with health checks and failover routing policies.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_profile" {
  name = "eb_ec2_profile"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_security_group" "myapp_sg" {
  name        = "myapp_sg"
  description = "Security group for RDS instances"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Replace with your CIDR block
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "myapp_subnet_blue" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"   # Replace with your CIDR block
  availability_zone = "us-west-2a"   # Replace with your AZ
}

resource "aws_subnet" "myapp_subnet_green" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.2.0/24"   # Replace with your CIDR block
  availability_zone = "us-west-2b"   # Replace with your AZ
}

resource "aws_db_instance" "myapp_db" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine         = "mysql"
  engine_version = "8.0"
  username       = "admin"
  password       = "password"
  db_name        = "myapp_db"
  skip_final_snapshot = true
}

resource "aws_db_instance" "myapp_db_blue" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine         = "mysql"
  engine_version = "8.0"
  username       = "admin"
  password       = "password"
  db_name        = "myapp_db"
  replicate_source_db = aws_db_instance.myapp_db.id
  skip_final_snapshot = true
}

resource "aws_db_instance" "myapp_db_green" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine         = "mysql"
  engine_version = "8.0"
  username       = "admin"
  password       = "password"
  db_name        = "myapp_db"
  replicate_source_db = aws_db_instance.myapp_db.id
  skip_final_snapshot = true
}

resource "aws_db_proxy" "myapp_db_proxy" {
  name               = "myapp_db_proxy"
  engine_family      = "MYSQL"
  role_arn           = aws_iam_role.eb_ec2_profile.arn
  vpc_subnet_ids     = [aws_subnet.myapp_subnet_blue.id, aws_subnet.myapp_subnet_green.id]
  vpc_security_group_ids = [aws_security_group.myapp_sg.id]

  auth {
    auth_scheme = "SECRETS"
    username    = "admin"
    secret_arn  = "arn:aws:secretsmanager:us-west-2:123456789012:secret:myapp_db_secret"
  }
}

resource "aws_route53_zone" "myapp_zone" {
  name = "example.com"
}

resource "aws_route53_health_check" "myapp_health_check" {
  type              = "HTTP"
  fully_qualified_domain_name = "myapp-db-proxy.example.com"
  port              = 3306
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
}

resource "aws_route53_record" "myapp_record_blue" {
  name    = "blue"
  type    = "A"
  zone_id = aws_route53_zone.myapp_zone.zone_id
  ttl     = 300

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.myapp_health_check.id

  records = [aws_db_instance.myapp_db_blue.endpoint]
}

resource "aws_route53_record" "myapp_record_green" {
  name    = "green"
  type    = "A"
  zone_id = aws_route53_zone.myapp_zone.zone_id
  ttl     = 300

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.myapp_health_check.id

  records = [aws_db_instance.myapp_db_green.endpoint]
}
```

### Notes

- Replace placeholder values such as `vpc-12345678`, `10.0.0.0/16`, `us-west-2a`, `us-west-2b`, and `arn:aws:secretsmanager:us-west-2:123456789012:secret:myapp_db_secret` with actual values relevant to your AWS environment.
- Ensure that the `aws_db_proxy` resource's `secret_arn` points to a valid Secrets Manager secret containing the database credentials.
- The `aws_route53_health_check` resource assumes that the DB proxy endpoint is accessible via HTTP on port 3306. Adjust the `type`, `port`, and `resource_path` as necessary based on your setup.

