### Description
This Terraform program creates an AWS Elastic Beanstalk application configured to run a Go application. It includes the necessary resources such as an Elastic Beanstalk application, an S3 bucket to store the application version source bundle, an S3 object representing the application version, and an Elastic Beanstalk application version. Additionally, it sets up a configuration template for the Elastic Beanstalk environment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name        = "go-app"
  description = "Elastic Beanstalk Application for Go"
}

resource "aws_s3_bucket" "elastic_beanstalk_bucket" {
  bucket = "go-app-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "elastic_beanstalk_app_version" {
  bucket = aws_s3_bucket.elastic_beanstalk_bucket.bucket
  key    = "go-app-version.zip"
  acl    = "private"
  source = "path/to/go-app-version.zip"
}

resource "aws_elastic_beanstalk_application_version" "elastic_beanstalk_app_version" {
  application = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  bucket      = aws_s3_bucket.elastic_beanstalk_bucket.bucket
  key         = aws_s3_object.elastic_beanstalk_app_version.key
  name        = "v1"
}

resource "aws_elastic_beanstalk_configuration_template" "elastic_beanstalk_config_template" {
  application          = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  name                 = "go-app-template"
  solution_stack_name  = "64bit Amazon Linux 2 v3.6.0 running Go 1.20"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:ec2:instances"
    name      = "InstanceType"
    value     = "t3.micro"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Elastic Beanstalk Application**: An Elastic Beanstalk application named `go-app` is created.
3. **S3 Bucket**: An S3 bucket named `go-app-bucket-<random-suffix>` is created to store the application version source bundle.
4. **Random String**: A random string is generated to ensure the S3 bucket name is unique.
5. **S3 Object**: An S3 object named `go-app-version.zip` is created in the S3 bucket, pointing to the local path of the Go application version source bundle.
6. **Elastic Beanstalk Application Version**: An Elastic Beanstalk application version is created, linking to the S3 bucket and object.
7. **Elastic Beanstalk Configuration Template**: A configuration template is created for the Elastic Beanstalk environment, specifying the solution stack for Go and setting autoscaling and instance type configurations.

