### Description
This Terraform program creates an Elastic Beanstalk application with an application version lifecycle. The lifecycle is configured to retain application versions for 5 days and delete them from S3 after that period. The program includes the necessary IAM role, S3 bucket, and S3 object to manage the application version source bundle.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "beanstalk_service_role" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "delete_s3_objects"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:DeleteObject",
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Effect = "Allow"
          Resource = [
            "${aws_s3_bucket.app_version_bucket.arn}",
            "${aws_s3_bucket.app_version_bucket.arn}/*"
          ]
        }
      ]
    })
  }
}

resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name = "my-elastic-beanstalk-app"

  appversion_lifecycle {
    service_role = aws_iam_role.beanstalk_service_role.arn
    max_age_in_days = 5
    delete_source_from_s3 = true
  }
}

resource "aws_s3_bucket" "app_version_bucket" {
  bucket = "my-elastic-beanstalk-app-version-bucket"
}

resource "aws_s3_object" "app_version_object" {
  bucket = aws_s3_bucket.app_version_bucket.bucket
  key    = "app-version.zip"
  source = "path/to/app-version.zip"
}

resource "aws_elastic_beanstalk_application_version" "elastic_beanstalk_app_version" {
  application = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  bucket      = aws_s3_bucket.app_version_bucket.bucket
  key         = aws_s3_object.app_version_object.key
  name        = "v1"
}
```

