    value = "Daisy"
  }
}

resource "aws_lex_slot_type" "pickup_date" {
  name = "pickup_date"
  value_selection_strategy = "ORIGINAL_VALUE"
}

resource "aws_lex_slot_type" "pickup_time" {
  name = "pickup_time"
  value_selection_strategy = "ORIGINAL_VALUE"
}

resource "aws_lex_intent" "order_flowers_intent" {
  name = "order_flowers_intent"

