### Description
This Terraform program creates an AWS Lex bot for booking a trip. It includes the following components:
1. **AWS Lex Bot**: The main bot resource that uses the defined intent.
2. **AWS Lex Intent**: Defines the intent for booking a trip, including a dialog code hook that triggers a Lambda function.
3. **AWS Lambda Function**: Handles the booking logic, using an IAM role for execution.
4. **AWS IAM Role**: Provides the necessary permissions for the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "lambda_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:CreateLogGroup",
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_lambda_function" "book_trip_lambda" {
  function_name = "book_trip_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  s3_bucket     = "your-lambda-code-bucket"
  s3_key        = "book_trip_lambda.zip"
}

resource "aws_lex_intent" "book_trip_intent" {
  name = "BookTripIntent"

  dialog_code_hook {
    message_version = "1.0"
    uri             = aws_lambda_function.book_trip_lambda.invoke_arn
  }

  confirmation_prompt {
    max_attempts = 2
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_bot" "book_trip_bot" {
  name               = "BookTripBot"
  child_directed     = false
  locale             = "en-US"
  intents {
    intent_name   = aws_lex_intent.book_trip_intent.name
    intent_version = "$LATEST"
  }
}
```

### Notes
- Ensure that the Lambda function code is uploaded to the specified S3 bucket (`your-lambda-code-bucket`) and key (`book_trip_lambda.zip`).
- Adjust the IAM role policy to allow necessary permissions for the Lambda function if additional permissions are required.

