### Description
This Terraform program creates an AWS Lex bot for ordering pizzas. It includes a Lambda function that handles the fulfillment of pizza orders. The bot uses intents and slot types to understand user inputs for pizza size and quantity. The necessary IAM roles and permissions are also set up to ensure proper execution.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lambda Function
resource "aws_iam_role" "pizza_order_role" {
  name = "pizza_order_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Execution
resource "aws_iam_role_policy" "pizza_order_policy" {
  name = "pizza_order_policy"
  role = aws_iam_role.pizza_order_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = [
          "lex:PostText",
          "lex:RecognizeText"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Lambda Function for Pizza Order Fulfillment
resource "aws_lambda_function" "pizza_order_lambda" {
  function_name = "pizza_order_lambda"
  role          = aws_iam_role.pizza_order_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      PIZZA_API_URL = "https://api.example.com/pizza"
    }
  }
}

# Slot Type for Pizza Size
resource "aws_lex_slot_type" "pizza_size_slot" {
  name = "PizzaSize"

  enumeration_value {
    value = "Small"
  }

  enumeration_value {
    value = "Medium"
  }

  enumeration_value {
    value = "Large"
  }
}

# Slot Type for Quantity
resource "aws_lex_slot_type" "quantity_slot" {
  name = "Quantity"

  enumeration_value {
    value = "1"
  }

  enumeration_value {
    value = "2"
  }

  enumeration_value {
    value = "3"
  }
}

# Intent to Order a Pizza
resource "aws_lex_intent" "order_pizza_intent" {
  name = "OrderPizza"

  slot {
    name             = "PizzaSize"
    slot_constraint  = "Required"
    slot_type        = aws_lex_slot_type.pizza_size_slot.name
    slot_type_version = "$LATEST"
  }

  slot {
    name             = "Quantity"
    slot_constraint  = "Required"
    slot_type        = aws_lex_slot_type.quantity_slot.name
    slot_type_version = "$LATEST"
  }

  dialog_code_hook {
    message_version = "1.0"
    uri             = aws_lambda_function.pizza_order_lambda.invoke_arn
  }
}

# Bot to Handle Pizza Orders
resource "aws_lex_bot" "order_pizza_bot" {
  name           = "OrderPizzaBot"
  child_directed = false

  intent {
    intent_name     = aws_lex_intent.order_pizza_intent.name
    intent_version  = "$LATEST"
  }
}
```

This Terraform configuration sets up an AWS Lex bot for ordering pizzas, including the necessary Lambda function, IAM roles, and slot types. The bot uses intents to understand user inputs for pizza size and quantity, and the Lambda function handles the fulfillment of these orders.

