This Terraform program creates a Kinesis Firehose Delivery Stream configured to deliver data to an Elasticsearch destination. It also sets up an IAM role with the necessary permissions for Kinesis Firehose to access both Elasticsearch and S3, and an S3 bucket to serve as a backup location for data processed by Kinesis Firehose.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_role" {
  name = "kinesis-firehose-elasticsearch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "firehose-elasticsearch-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "es:DescribeElasticsearchDomain",
            "es:DescribeElasticsearchDomainConfig",
            "es:ESHttpPost",
            "es:ESHttpPut",
            "es:ESHttpGet",
            "es:ESHttpDelete",
            "es:ESHttpHead"
          ]
          Effect = "Allow"
          Resource = "*"
        },
        {
          Action = [
            "s3:AbortMultipartUpload",
            "s3:GetBucketLocation",
            "s3:GetObject",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = [
            aws_s3_bucket.firehose_backup_bucket.arn,
            "${aws_s3_bucket.firehose_backup_bucket.arn}/*"
          ]
        }
      ]
    })
  }
}

resource "aws_s3_bucket" "firehose_backup_bucket" {
  bucket = "kinesis-firehose-backup-bucket-${random_string.bucket_suffix.result}"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name = "kinesis-firehose-delivery-stream"

  elasticsearch_configuration {
    domain_arn         = "arn:aws:es:us-west-2:123456789012:domain/my-elasticsearch-domain"
    index_name         = "my-index"
    role_arn           = aws_iam_role.firehose_role.arn
    type_name          = "my-type"
    buffering_interval = 300
    buffering_size     = 5
    retry_duration     = 300
    s3_backup_mode     = "Failed"
    s3_configuration {
      bucket_arn = aws_s3_bucket.firehose_backup_bucket.arn
      role_arn   = aws_iam_role.firehose_role.arn
    }
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `kinesis-firehose-elasticsearch-role` is created with a trust policy allowing Kinesis Firehose to assume the role. Inline policies are added to grant permissions for Elasticsearch operations and S3 operations on the backup bucket.
3. **S3 Bucket**: An S3 bucket named `kinesis-firehose-backup-bucket-{random_suffix}` is created to store backup data. A random string suffix is appended to ensure the bucket name is unique.
4. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream is created with an Elasticsearch destination. The stream is configured to buffer data for 300 seconds or 5 MB before sending it to Elasticsearch. The backup mode is set to `Failed`, meaning data that fails to send to Elasticsearch will be stored in the S3 bucket.

