            aws_s3_bucket.firehose_splunk_bucket.arn,
            "${aws_s3_bucket.firehose_splunk_bucket.arn}/*"
          ]
        },
        {
          Action = [
            "logs:CreateLogDelivery",
            "logs:DescribeLogGroups",
            "logs:DescribeLogStreams",
            "logs:PutLogEvents",
            "logs:UpdateLogDelivery"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_to_splunk" {
  name = "firehose-to-splunk"

  splunk_configuration {
    hec_endpoint       = "https://hec.splunkcloud.com:8088/services/collector/event"
    hec_token          = "your_splunk_hec_token"
    role_arn           = aws_iam_role.firehose_splunk_role.arn
    s3_backup_mode     = "Enabled"
    buffering_interval = 60
    buffering_size     = 5
  }

  s3_configuration {
    role_arn           = aws_iam_role.firehose_splunk_role.arn
    bucket_arn         = aws_s3_bucket.firehose_splunk_bucket.arn
    buffering_interval = 300
    buffering_size     = 5
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
- **S3 Bucket**: An S3 bucket named `firehose-splunk-bucket` is created for storing intermediate data.
- **IAM Role**: An IAM role named `firehose-splunk-role` is created with a trust policy allowing Firehose to assume the role. Inline policies grant permissions for S3 operations and CloudWatch Logs.
- **Kinesis Firehose Delivery Stream**: A Firehose delivery stream named `firehose-to-splunk` is created with a Splunk destination and an S3 backup configuration. The `hec_endpoint` and `hec_token` need to be replaced with actual values from your Splunk setup.
- **Random String**: A random string is appended to the S3 bucket name to ensure uniqueness.

