### Description
This Terraform program creates a Kinesis Firehose Delivery Stream configured to deliver data to an OpenSearch Serverless collection. The delivery stream is set up to back up data to an S3 bucket. Additionally, an IAM role is created to grant the necessary permissions for Kinesis Firehose to access both OpenSearch Serverless and S3. The configuration also includes VPC settings for the delivery stream.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_role" {
  name = "kinesis-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "firehose-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:AbortMultipartUpload",
            "s3:GetBucketLocation",
            "s3:GetObject",
            "s3:ListBucket",
            "s3:ListBucketMultipartUploads",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = [
            aws_s3_bucket.backup_bucket.arn,
            "${aws_s3_bucket.backup_bucket.arn}/*"
          ]
        },
        {
          Action = [
            "es:DescribeElasticsearchDomain",
            "es:DescribeElasticsearchDomainConfig",
            "es:ESHttpPut",
            "es:ESHttpPost",
            "es:ESHttpDelete",
            "es:ESHttpGet"
          ]
          Effect = "Allow"
          Resource = aws_opensearchserverless_collection.opensearch_collection.arn
        }
      ]
    })
  }
}

resource "aws_s3_bucket" "backup_bucket" {
  bucket = "kinesis-firehose-backup-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "aws_opensearchserverless_collection" "opensearch_collection" {
  name = "kinesis-firehose-collection"
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name = "kinesis-firehose-stream"

  opensearchserverless_configuration {
    collection_endpoint = aws_opensearchserverless_collection.opensearch_collection.collection_endpoint
    index_name          = "firehose-index"
    role_arn            = aws_iam_role.firehose_role.arn
    s3_configuration {
      bucket_arn = aws_s3_bucket.backup_bucket.arn
      role_arn   = aws_iam_role.firehose_role.arn
    }
  }

  vpc_config {
    subnet_ids         = ["subnet-12345678", "subnet-87654321"]
    security_group_ids = ["sg-12345678"]
    role_arn           = aws_iam_role.firehose_role.arn
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `kinesis-firehose-role` is created with a trust policy allowing Kinesis Firehose to assume the role. Inline policies grant permissions for S3 and OpenSearch Serverless operations.
3. **S3 Bucket**: An S3 bucket named `kinesis-firehose-backup-bucket-{random_string}` is created for data backup. The bucket name includes a random suffix to ensure uniqueness.
4. **OpenSearch Serverless Collection**: An OpenSearch Serverless collection named `kinesis-firehose-collection` is created.
5. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream named `kinesis-firehose-stream` is configured to deliver data to the OpenSearch Serverless collection and back up data to the S3 bucket. VPC settings are included to ensure the delivery stream operates within a VPC.
6. **Random String**: A random string resource is used to generate a unique suffix for the S3 bucket name.

