        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "kinesis-analytics-cloudwatch-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "logs:PutLogEvents",
            "logs:CreateLogStream",
            "logs:DescribeLogStreams"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_cloudwatch_log_group" "kinesis_analytics_log_group" {
  name = "/aws/kinesis-analytics/basic-kinesis-analytics-app"
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics_log_stream" {
  name           = "basic-kinesis-analytics-app-log-stream"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics_log_group.name
}

resource "aws_kinesis_analytics_application" "basic_kinesis_analytics_app" {
  name = "basic-kinesis-analytics-app"

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
    role_arn       = aws_iam_role.kinesis_analytics_role.arn
  }
}
```

This Terraform configuration sets up the necessary AWS resources to create a Kinesis Analytics application with CloudWatch logging. The IAM role is configured to allow the Kinesis Analytics service to write logs to the specified CloudWatch log stream.

