This Terraform program creates an Amazon Kendra index and a data source associated with that index. The data source is configured to crawl web content with specific URL exclusion and inclusion patterns. The program includes the necessary IAM roles and permissions to ensure proper operation.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_role" {
  name = "kendra-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kendra_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKendraFullAccess"
  role       = aws_iam_role.kendra_role.name
}

resource "aws_kendra_index" "kendra_index" {
  name     = "my-kendra-index"
  role_arn = aws_iam_role.kendra_role.arn

  capacity_units {
    query_capacity_units   = 2
    storage_capacity_units = 5
  }
}

resource "aws_kendra_data_source" "kendra_data_source" {
  index_id = aws_kendra_index.kendra_index.id
  name     = "my-kendra-web-crawler"
  type     = "WEBCRAWLER"
  role_arn = aws_iam_role.kendra_role.arn

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
        url_inclusion_patterns = ["https://example.com/included/*"]
        url_exclusion_patterns = ["https://example.com/excluded/*"]
      }
    }
  }
}
