This Terraform program sets up an AWS EKS cluster with an associated Fargate profile for the 'kube-system' namespace. It creates the necessary IAM roles and attaches the appropriate policies. Additionally, it uses a `null_resource` to patch the Kubernetes deployment 'coredns' in the 'kube-system' namespace using the EKS cluster's endpoint, certificate authority, and authentication token.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM role for EKS cluster
resource "aws_iam_role" "cluster_role" {
  name = "eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

# IAM role policy attachment for EKS cluster
resource "aws_iam_role_policy_attachment" "attach_eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster_role.name
}

# IAM role for EKS Fargate profile
resource "aws_iam_role" "eks_fargate_profile_role" {
  name = "eks-fargate-profile-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "fargate.amazonaws.com"
        }
      }
    ]
  })
}

# IAM role policy attachment for EKS Fargate profile
resource "aws_iam_role_policy_attachment" "attach_amazon_eks_fargate_pod_execution_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
  role       = aws_iam_role.eks_fargate_profile_role.name
}

# VPC and subnets for EKS cluster
resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "eks-subnet1"
  }
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.example_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "eks-subnet2"
  }
}

# EKS cluster
resource "aws_eks_cluster" "example_cluster" {
  name     = "example-eks-cluster"
  role_arn = aws_iam_role.cluster_role.arn

  vpc_config {
    subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
  }
}

# EKS Fargate profile for kube-system namespace
resource "aws_eks_fargate_profile" "kube_system_fargate_profile" {
  cluster_name         = aws_eks_cluster.example_cluster.name
  fargate_profile_name = "kube-system-profile"
  pod_execution_role_arn = aws_iam_role.eks_fargate_profile_role.arn

  selector {
    namespace = "kube-system"
  }
}

# Null resource to patch coredns deployment
resource "null_resource" "patch_coredns" {
  provisioner "local-exec" {
    command = <<-EOT
      kubectl --server=${aws_eks_cluster.example_cluster.endpoint} \
              --certificate-authority-data=${base64decode(aws_eks_cluster.example_cluster.certificate_authority[0].data)} \
              --token=${data.aws_eks_cluster_auth.example_cluster.token} \
              patch deployment coredns -n kube-system -p '{"spec":{"template":{"metadata":{"annotations":{"kubectl.kubernetes.io/restartedAt":"'$(date +%s)'"}}}}}'
    EOT
  }

  depends_on = [
    aws_eks_cluster.example_cluster,
  ]
}

# Data source to get EKS cluster auth
data "aws_eks_cluster_auth" "example_cluster" {
  name = aws_eks_cluster.example_cluster.name
}
