### Description
This Terraform script provisions an AWS EKS cluster named "example" with the necessary IAM role and VPC configuration. It includes dependencies on IAM role policy attachments and outputs the cluster's endpoint and kubeconfig certificate authority data.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the EKS cluster
resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the AmazonEKSClusterPolicy policy to the IAM role
resource "aws_iam_role_policy_attachment" "eks_cluster_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

# Create subnets for the EKS cluster
resource "aws_subnet" "subnet_az1" {
  vpc_id            = "vpc-12345678"
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = "vpc-12345678"
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = "vpc-12345678"
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

# Create the EKS cluster
resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id
    ]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy_attachment
  ]
}

# Outputs for the cluster's endpoint and kubeconfig certificate authority data
output "cluster_endpoint" {
  value = aws_eks_cluster.example.endpoint
}

output "certificate_authority_data" {
  value = base64decode(aws_eks_cluster.example.certificate_authority[0].data)
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **IAM Role**: An IAM role named `eks-cluster-role` is created with an assume role policy allowing EKS to assume the role.
- **IAM Role Policy Attachment**: The `AmazonEKSClusterPolicy` policy is attached to the IAM role.
- **Subnets**: Three subnets are created in different availability zones (`us-west-2a`, `us-west-2b`, `us-west-2c`) within a specified VPC (`vpc-12345678`).
- **EKS Cluster**: An EKS cluster named `example` is created with the specified IAM role and VPC configuration.
- **Outputs**: The cluster's endpoint and kubeconfig certificate authority data are outputted for further use.

