### Description
This Terraform program sets up an AWS S3 bucket and a DynamoDB table for Terraform state management. The S3 bucket is configured with versioning, server-side encryption using AES256, and public access restrictions to prevent accidental deletion. The DynamoDB table is set up with a hash key named 'LockID' using the 'PAY_PER_REQUEST' billing mode for Terraform locking.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "terraform_state_bucket" {
  bucket = "terraform-state-bucket-${var.environment}"
  acl    = "private"
  force_destroy = false

  tags = {
    Name        = "TerraformStateBucket"
    Environment = var.environment
  }
}

resource "aws_s3_bucket_versioning" "terraform_state_bucket_versioning" {
  bucket = aws_s3_bucket.terraform_state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_bucket_encryption" {
  bucket = aws_s3_bucket.terraform_state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_acl" "terraform_state_bucket_acl" {
  bucket = aws_s3_bucket.terraform_state_bucket.id
  acl    = "private"
}

resource "aws_dynamodb_table" "terraform_state_lock_table" {
  name         = "terraform-state-lock-table-${var.environment}"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "LockID"
    type = "S"
  }

  key_schema {
    attribute_name = "LockID"
    key_type       = "HASH"
  }

  tags = {
    Name        = "TerraformStateLockTable"
    Environment = var.environment
  }
}

variable "environment" {
  description = "Environment name for resource tagging"
  default     = "dev"
}
```

This Terraform configuration ensures that the S3 bucket is properly secured and configured for Terraform state management, while the DynamoDB table is set up for locking purposes. The `environment` variable is used to tag resources for easier identification and management across different environments.

