  }
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "EC2InstanceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_security_group" "web_server_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "WebServerSG"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "WebServerSG"
  }
}

resource "aws_security_group" "app_server_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "AppServerSG"

  ingress {
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = ["10.0.1.0/24"]  # Allow traffic from public subnet
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AppServerSG"
  }
}

resource "aws_security_group" "db_server_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "DBServerSG"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.2.0/24"]  # Allow traffic from private subnet 1
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBServerSG"
  }
}

resource "aws_instance" "web_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public_subnet.id
  iam_instance_profile = aws_iam_role.ec2_instance_role.name
  vpc_security_group_ids = [aws_security_group.web_server_sg.id]

  tags = {
    Name = "WebServer"
  }
}

resource "aws_instance" "app_server" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.private_subnet_1.id
  iam_instance_profile = aws_iam_role.ec2_instance_role.name
  vpc_security_group_ids = [aws_security_group.app_server_sg.id]

  tags = {
    Name = "AppServer"
  }
}

resource "aws_db_instance" "rds_database" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "8.0"
  username = "admin"
  password = "password"
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_server_sg.id]

  tags = {
    Name = "RDSDatabase"
  }
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rdssubnetgroup"
  subnet_ids = [aws_subnet.private_subnet_2.id]

  tags = {
    Name = "RDSSubnetGroup"
  }
}
```

This Terraform configuration sets up a VPC with three subnets: one public subnet and two private subnets. It also creates an EC2 instance in the public subnet running web servers, an EC2 instance in the private subnet running application servers, and an RDS instance in the other private subnet serving as the database. The necessary IAM roles, security groups, and dependencies are also defined.

