### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "sagemaker_pipeline_role" {
  name = "sagemaker-pipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AmazonSageMakerFullAccess"
  ]
}

resource "aws_s3_bucket" "sagemaker_pipeline_bucket" {
  bucket = "sagemaker-pipeline-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "sagemaker_pipeline_object" {
  bucket = aws_s3_bucket.sagemaker_pipeline_bucket.bucket
  key    = "pipeline-definition.json"
  acl    = "private"

  content = jsonencode({
    Version = "2018-10-01"
    Steps = [
      {
        Name = "Step1"
        Arguments = {
          "ProcessingInputConfig" = [
            {
              InputName = "input1"
              S3Input = {
                S3Uri = "s3://${aws_s3_bucket.sagemaker_pipeline_bucket.bucket}/input-data/"
                LocalPath = "/opt/ml/processing/input"
              }
            }
          ]
        }
      }
    ]
  })
}

resource "aws_sagemaker_pipeline" "sagemaker_pipeline" {
  pipeline_name     = "sagemaker-pipeline"
  pipeline_display_name = "SageMaker Pipeline"
  role_arn          = aws_iam_role.sagemaker_pipeline_role.arn

  pipeline_definition_s3_location {
    bucket = aws_s3_bucket.sagemaker_pipeline_bucket.bucket
    object_key = aws_s3_object.sagemaker_pipeline_object.key
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `sagemaker-pipeline-role` is created with a trust policy allowing SageMaker to assume the role. It also attaches the `AmazonSageMakerFullAccess` managed policy.
3. **S3 Bucket**: An S3 bucket named `sagemaker-pipeline-bucket` with a random suffix is created to store the pipeline definition.
4. **S3 Object**: An S3 object named `pipeline-definition.json` is created in the S3 bucket. This object contains a simple JSON representation of a SageMaker pipeline step.
5. **SageMaker Pipeline**: A SageMaker pipeline is created with the specified name, display name, and role ARN. The pipeline definition is stored in the S3 object created earlier.

This configuration ensures that all dependencies are correctly set up and that the SageMaker pipeline can be deployed using Terraform.

