### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "sagemaker_role" {
  name = "sagemaker-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_policy" {
  role       = aws_iam_role.sagemaker_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonSageMakerFullAccess"
}

resource "aws_s3_bucket" "sagemaker_data_capture_bucket" {
  bucket = "sagemaker-data-capture-${var.environment}"
  acl    = "private"
}

resource "aws_sagemaker_model" "sagemaker_model" {
  name            = "sagemaker-model-${var.environment}"
  execution_role_arn = aws_iam_role.sagemaker_role.arn

  primary_container {
    image           = "763104351884.dkr.ecr.us-west-2.amazonaws.com/tensorflow-inference:2.3.0-cpu-py37-ubuntu18.04"
    model_data_url  = "s3://my-bucket/model.tar.gz"
  }
}

resource "aws_sagemaker_endpoint_configuration" "sagemaker_endpoint_configuration" {
  name = "sagemaker-endpoint-config-${var.environment}"

  production_variants {
    model_name     = aws_sagemaker_model.sagemaker_model.name
    instance_type  = "ml.m5.large"
    initial_instance_count = 1
  }

