### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false
  availability_zone       = "us-west-2b"
  tags = {
    Name = "PrivateSubnet"
  }
}

resource "aws_launch_template" "aws_linux_2_template" {
  name          = "aws-linux-2-template"
  image_id      = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"

  network_interfaces {
    associate_public_ip_address = true
    subnet_id                   = aws_subnet.public_subnet.id
  }

  tags = {
    Name = "AWSLinux2Template"
  }
}

resource "aws_ec2_fleet" "ec2_fleet" {
  launch_template_config {
    launch_template {
      id      = aws_launch_template.aws_linux_2_template.id
      version = "$Latest"
    }
  }

  target_capacity_specification {
    total_target_capacity     = 9
    default_target_capacity_type = "spot"
    spot_target_capacity      = 4
    on_demand_target_capacity = 5
  }

  spot_options {
    allocation_strategy = "lowest-price"
    instance_interruption_behavior = "terminate"
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  tags = {
    Name = "EC2Fleet"
  }
}
```

This Terraform configuration sets up a VPC with a public and private subnet, and an EC2 Fleet with the specified instance types and configurations. The launch template is configured to use the public subnet, and the EC2 Fleet is set up with both On-Demand and Spot Instances.

