### Description
The Terraform program below sets up an ElastiCache user with password authentication. It includes creating an ElastiCache user, an ElastiCache user group, and a Cognito User Pool. The ElastiCache user is added to the user group, and the Cognito User Pool is configured to manage the authentication process for the ElastiCache user.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_elasticache_user" "elasticache_user" {
  user_id     = "my-elasticache-user"
  user_name   = "my-elasticache-user"
  access_string = "on ~app::* -@allusers"
  engine      = "redis"

  authentication_mode {
    type = "password"
    passwords = ["securePassword123"]
  }
}

resource "aws_elasticache_user_group" "elasticache_user_group" {
  user_group_id = "my-elasticache-user-group"
  engine        = "redis"
  user_ids      = [aws_elasticache_user.elasticache_user.user_id]
}

resource "aws_cognito_user_pool" "cognito_user_pool" {
  name = "my-elasticache-cognito-pool"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length              = 8
    require_lowercase           = true
    require_numbers             = true
    require_symbols             = true
    require_uppercase           = true
    temporary_password_validity_days = 7
  }

  schema {
    attribute_data_type = "String"
    name                = "email"
    required            = true
  }

  schema {
    attribute_data_type = "String"
    name                = "phone_number"
    required            = false
  }
}
```

This Terraform configuration sets up the necessary resources to authenticate an ElastiCache user with passwords using AWS services. The `aws_elasticache_user` resource creates a user with a specified access string and password. The `aws_elasticache_user_group` resource manages the user, and the `aws_cognito_user_pool` resource handles the authentication process.

