### Description
This Terraform program creates an Amazon DynamoDB Accelerator (DAX) cluster with the following specifications:
- Node type: `dax.r4.large`
- Replication factor: `1`
- An IAM role named `dax_role` with the necessary permissions for DAX operations.
- A parameter group named `dax_param_group`.

The DAX cluster depends on both the IAM role and the parameter group. The IAM role includes an inline policy that allows DAX operations, and the parameter group is configured with default parameters.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_iam_role" "dax_role" {
  name = "dax_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "dax_policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "dynamodb:*",
            "ec2:Describe*",
            "ec2:CreateNetworkInterface",
            "ec2:DeleteNetworkInterface",
            "ec2:DescribeNetworkInterfaces",
            "ec2:DescribeSubnets",
            "ec2:DescribeSecurityGroups",
            "cloudwatch:*",
            "logs:*"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_dax_parameter_group" "dax_param_group" {
  name = "dax_param_group"

  parameters {
    name  = "record-ttl-millis"
    value = "3600000"
  }

  parameters {
    name  = "query-ttl-millis"
    value = "3600000"
  }
}

resource "aws_dax_cluster" "dax_cluster" {
  cluster_name       = "my-dax-cluster"
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  parameter_group_name = aws_dax_parameter_group.dax_param_group.name
}
```

This Terraform configuration sets up the necessary resources to create a DAX cluster with the specified parameters and dependencies. The IAM role and parameter group are created first, and then the DAX cluster is created, referencing these resources.

