### Description
This Terraform program creates an Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. It also sets up the necessary subnets, security group, and IAM role required for the MSK cluster to function properly. The configuration ensures that the MSK cluster is deployed in a VPC with appropriate networking and security settings.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "msk-subnet-az1"
  }
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "msk-subnet-az2"
  }
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
  tags = {
    Name = "msk-subnet-az3"
  }
}

resource "aws_security_group" "msk_security_group" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "msk-security-group"
  }
}

resource "aws_iam_role" "msk_service_execution_role" {
  name = "msk-service-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "msk-service-execution-role"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  tags = {
    Name = "my-msk-cluster"
  }
}
```

This Terraform configuration sets up an MSK cluster with 3 broker nodes in a VPC across three different availability zones. It includes the necessary subnets, security group, and IAM role to ensure the MSK cluster is properly configured and secure.

