### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region. The MSK cluster is configured to log to an S3 bucket. The program includes the creation of a VPC, subnets, a security group, an IAM role, and the S3 bucket for logging. All resources are interconnected based on their dependencies.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-east-1c"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "msk-security-group"

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_iam_role" {
  name = "msk-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_sg.id]
  }

  logging_info {
    s3 {
      bucket  = aws_s3_bucket.msk_logs_bucket.bucket
      prefix  = "msk-logs/"
    }
  }
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.suffix.result}"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_s3_bucket_acl" "msk_logs_bucket_acl" {
  bucket = aws_s3_bucket.msk_logs_bucket.bucket
  acl    = "private"
}

resource "aws_s3_bucket_logging" "msk_logs_bucket_logging" {
  bucket        = aws_s3_bucket.msk_logs_bucket.bucket
  target_bucket = aws_s3_bucket.msk_logs_bucket.bucket
  target_prefix = "logs/"
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **VPC and Subnets**: A VPC is created with three subnets in different availability zones (`us-east-1a`, `us-east-1b`, `us-east-1c`).
3. **Security Group**: A security group is created for the MSK cluster, allowing inbound traffic on port 9092 and all outbound traffic.
4. **IAM Role**: An IAM role is created for the MSK cluster with a trust policy allowing EC2 to assume the role.
5. **MSK Cluster**: The MSK cluster is created with three broker nodes, using the subnets and security group created earlier. Logging is configured to send logs to an S3 bucket.
6. **S3 Bucket**: An S3 bucket is created for storing the MSK logs. The bucket name is made unique using a random string suffix.
7. **S3 Bucket ACL and Logging**: The S3 bucket's ACL is set to private, and logging is configured to store logs in the same bucket under the `logs/` prefix.

