### Description
The Terraform program below creates an Amazon RDS MySQL cluster with three instances, each allocated 100 GB of storage. The instances are distributed across three different availability zones within a specified region. The program includes necessary IAM roles and configurations to ensure the cluster is properly set up.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_db_subnet_group" "mysql_subnet_group" {
  name       = "mysql-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210", "subnet-01a2b3c4d5e6f7g8h"]  # Replace with your subnet IDs
}

resource "aws_db_instance" "mysql_cluster" {
  count              = 3
  identifier         = "mysql-instance-${count.index}"
  instance_class     = "db.t3.medium"  # Choose an appropriate instance class
  allocated_storage  = 100
  engine             = "mysql"
  engine_version     = "8.0"
  username           = "admin"
  password           = "securepassword"
  db_subnet_group_name = aws_db_subnet_group.mysql_subnet_group.name
  vpc_security_group_ids = ["sg-0123456789abcdef0"]  # Replace with your security group ID
  iam_database_authentication_enabled = true
  iam_roles          = [aws_iam_role.rds_iam_role.arn]
  availability_zone  = element(["us-west-2a", "us-west-2b", "us-west-2c"], count.index)
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with the region `us-west-2`. You can change this to your preferred region.
- **IAM Role**: An IAM role named `rds-iam-role` is created with a trust policy allowing RDS to assume the role.
- **IAM Role Policy Attachment**: The `AmazonRDSFullAccess` policy is attached to the IAM role.
- **DB Subnet Group**: A DB subnet group is created with specified subnet IDs. Replace these with your actual subnet IDs.
- **DB Instances**: Three MySQL instances are created, each with 100 GB of storage. They are distributed across three different availability zones (`us-west-2a`, `us-west-2b`, `us-west-2c`). Replace the security group ID with your actual security group ID.

This configuration ensures that the MySQL cluster is properly set up with the required storage and IAM permissions.

