          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_eks_cluster" "my_eks_cluster" {
  name     = "my-eks-cluster"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.subnet_us_east_1a.id,
      aws_subnet.subnet_us_east_1b.id,
      aws_subnet.subnet_us_east_1c.id
    ]
  }
}

resource "aws_rds_cluster" "my_sql_cluster" {
  engine               = "aurora-mysql"
  allocated_storage    = 100
  availability_zones   = ["us-east-1a", "us-east-1b", "us-east-1c"]
  db_cluster_identifier = "my-sql-cluster"
  db_subnet_group_name  = "default"  # Assuming a default DB subnet group exists
  master_username       = "admin"
  master_password       = "password123"  # Replace with a secure password
}
```

This Terraform configuration sets up an AWS environment with a VPC, subnets in three different availability zones, an IAM role for an EKS cluster, an EKS cluster itself, and a MySQL cluster using Aurora. The MySQL cluster is configured with 100 GB of storage across the specified availability zones.

