This Terraform program creates an AWS Redshift cluster with a custom parameter group and an event subscription that sends events to an AWS SNS topic. The dependencies between the resources are managed to ensure proper creation order.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_sns_topic" "redshift_events_topic" {
  name = "redshift-events-topic"
}

resource "aws_redshift_parameter_group" "redshift_param_group" {
  name   = "redshift-param-group"
  family = "redshift-1.x"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "query_group"
    value = "example"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "tf-redshift-cluster"
  node_type          = "dc1.large"
  database_name      = "mydb"
