### Description
This Terraform program creates two AWS S3 buckets: one for storing objects (`source_bucket`) and another for storing CSV inventory reports (`inventory_bucket`). It configures a weekly inventory report for the `source_bucket` and stores the report in the `inventory_bucket`. Additionally, it sets up an IAM role and a DLM lifecycle policy to manage the inventory process.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "source_bucket" {
  bucket = "my-source-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "aws_s3_bucket" "inventory_bucket" {
  bucket = "my-inventory-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "aws_s3_bucket_inventory" "weekly_inventory" {
  bucket = aws_s3_bucket.source_bucket.id
  name   = "weekly-inventory"

  included_object_versions = "All"
  schedule {
    frequency = "Weekly"
  }

  destination {
    s3_bucket_destination {
      bucket = aws_s3_bucket.inventory_bucket.arn
      format = "CSV"
      prefix = "inventory-reports/"
    }
  }
}

resource "aws_iam_role" "dlm_inventory_role" {
  name = "dlm-inventory-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "dlm_inventory_policy" {
  name = "dlm-inventory-policy"
  role = aws_iam_role.dlm_inventory_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetInventoryConfiguration",
          "s3:PutInventoryConfiguration",
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.source_bucket.arn,
          aws_s3_bucket.inventory_bucket.arn
        ]
      }
    ]
  })
}

resource "aws_dlm_lifecycle_policy" "dlm_inventory_policy" {
  description          = "Weekly Inventory Report Policy"
  execution_role_arn = aws_iam_role.dlm_inventory_role.arn

  policy_details {
    resource_types = ["VOLUME"]
    target_tags = {
      Name = "inventory-bucket"
    }
    schedule {
      name = "WeeklySchedule"
      create_rule {
        interval      = 7
        interval_unit = "DAY"
        times         = ["23:00"]
      }
      retain_rule {
        count = 1
      }
    }
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
```

