### Description
This Terraform program sets up an infrastructure for an autograder using AWS CodeBuild and S3. The autograder will run students' code stored on GitHub and store the results in an S3 bucket. The program includes an IAM role for CodeBuild to interact with AWS services, specifically GitHub and S3.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "autograder-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Effect = "Allow"
          Resource = "arn:aws:s3:::autograder-results/*"
        },
        {
          Action = [
            "github:ListRepos",
            "github:GetRepo"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_s3_bucket" "autograder_results" {
  bucket = "autograder-results"
  acl    = "private"
}

resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder-project"
  service_role = aws_iam_role.autograder_codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    report_build_status = true
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }
}
```

