### Description

This Terraform configuration sets up an infrastructure for an autograder using AWS CodeBuild and AWS VPC. The autograder runs students' code stored on GitHub in a secure environment isolated from the internet. The configuration includes:

1. **AWS IAM Role**: An IAM role for CodeBuild with necessary permissions.
2. **AWS VPC**: A Virtual Private Cloud to isolate the CodeBuild environment.
3. **AWS Subnet**: A subnet within the VPC.
4. **AWS Security Group**: A security group configured to deny all outbound traffic.
5. **AWS CodeBuild Project**: A CodeBuild project configured to run students' code within the VPC and using the specified security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "autograder_sg" {
  vpc_id = aws_vpc.autograder_vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    self        = false
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder-project"
  service_role = aws_iam_role.autograder_codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    buildspec       = "buildspec.yml"
    auth {
      type     = "OAUTH"
      resource = "arn:aws:codebuild:us-west-2:123456789012:project/autograder-project"
    }
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = [aws_subnet.autograder_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }
}
```

This configuration ensures that the autograder environment is secure and isolated from the internet, while still allowing necessary network access for CodeBuild operations.

