  bucket = "students-codebuild-output-bucket"
  acl    = "private"
}

resource "aws_vpc" "codebuild_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "codebuild_subnet" {
  vpc_id     = aws_vpc.codebuild_vpc.id
  cidr_block = "10.0.0.0/24"
}

resource "aws_security_group" "codebuild_sg" {
  vpc_id = aws_vpc.codebuild_vpc.id
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

data "aws_iam_policy_document" "codebuild_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild_role" {
  name               = "codebuild-service-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role_policy.json
}

resource "aws_codebuild_project" "codebuild_project" {
  name         = "students_codebuild_project"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.codebuild_output_bucket.bucket}/artifacts"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type            = "GITHUB"
    location        = "github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id             = aws_vpc.codebuild_vpc.id
    subnets            = [aws_subnet.codebuild_subnet.id]
    security_group_ids = [aws_security_group.codebuild_sg.id]
  }
}
```

