### Description
This Terraform program sets up an AWS infrastructure to run a code every day at 7 UTC using AWS EventBridge. The program includes the following components:

1. **AWS CloudWatch Event Rule**: This rule is scheduled to trigger daily at 7 UTC.
2. **AWS Lambda Function**: This function contains the code that will be executed daily.
3. **AWS Lambda Permission**: This permission allows the EventBridge rule to invoke the Lambda function.
4. **AWS CloudWatch Event Target**: This target specifies the Lambda function as the destination for the EventBridge rule.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Default region, can be changed as needed
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "daily_code_runner" {
  function_name = "daily_code_runner"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "function.zip"

  environment {
    variables = {
      LOG_LEVEL = "INFO"
    }
  }
}

resource "aws_lambda_permission" "allow_eventbridge_invocation" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_code_runner.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_code_run.arn
}

resource "aws_cloudwatch_event_rule" "daily_code_run" {
  name                = "daily_code_run"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_code_run.name
  target_id = "RunDailyCode"
  arn       = aws_lambda_function.daily_code_runner.arn
}
```

