### Description
This Terraform program sets up the infrastructure for a video streaming site using AWS CloudFront and AWS S3. The program creates an S3 bucket to store the video content and a CloudFront distribution to distribute the content globally. The S3 bucket is configured with the necessary permissions to allow CloudFront to access its contents.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  logging {
    target_bucket = "video-content-bucket-logs-${random_string.bucket_suffix.result}"
    target_prefix = "log/"
  }

  tags = {
    Name = "VideoContentBucket"
  }
}

resource "aws_s3_bucket" "video_content_bucket_logs" {
  bucket = "video-content-bucket-logs-${random_string.bucket_suffix.result}"
  acl    = "log-delivery-write"

  tags = {
    Name = "VideoContentBucketLogs"
  }
}

resource "aws_iam_role" "cloudfront_origin_access_identity" {
  name = "cloudfront-origin-access-identity"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "cloudfront_origin_access_policy" {
  name        = "cloudfront-origin-access-policy"
  description = "Policy to allow CloudFront to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_content_bucket.bucket}/*"
        Principal = {
          AWS = aws_iam_role.cloudfront_origin_access_identity.arn
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_cloudfront_policy_to_role" {
  role       = aws_iam_role.cloudfront_origin_access_identity.name
  policy_arn = aws_iam_policy.cloudfront_origin_access_policy.arn
}

resource "aws_cloudfront_origin_access_identity" "origin_access_identity" {
  comment = "Origin Access Identity for CloudFront to access S3 bucket"
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  enabled = true

  origin {
    domain_name = "${aws_s3_bucket.video_content_bucket.bucket}.s3.amazonaws.com"
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.origin_access_identity.cloudfront_access_identity_path
    }
  }

