### Description
This Terraform program sets up the infrastructure for a video streaming site using AWS Load Balancing. It includes an Application Load Balancer (ALB), a target group, and two EC2 instances to balance the load. The program ensures that the load balancer depends on the target group, and the target group depends on the EC2 instances.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "video_streaming_subnet_1" {
  vpc_id            = aws_vpc.video_streaming_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "video_streaming_subnet_2" {
  vpc_id            = aws_vpc.video_streaming_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "video_streaming_sg" {
  name        = "video_streaming_sg"
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = aws_subnet.video_streaming_subnet_1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.video_streaming_subnet_2.id
  }

  security_groups = [aws_security_group.video_streaming_sg.id]
}

resource "aws_lb_target_group" "video_streaming_target_group" {
  name     = "video-streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_instance" "video_streaming_server" {
  count         = 2
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = element([aws_subnet.video_streaming_subnet_1.id, aws_subnet.video_streaming_subnet_2.id], count.index % 2)
  security_groups = [aws_security_group.video_streaming_sg.name]

  tags = {
    Name = "video-streaming-server-${count.index}"
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_target_group_attachment" {
  count            = 2
  target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  target_id        = aws_instance.video_streaming_server[count.index].id
  port             = 80
}
```

This Terraform configuration sets up a basic infrastructure for a video streaming site using AWS Load Balancing. It includes a VPC, subnets, security groups, an Application Load Balancer, a target group, and two EC2 instances. The load balancer is configured to distribute traffic across the two EC2 instances.

