  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "video-streaming.com"
}

resource "aws_route53_record" "video_streaming_record" {
  name    = "www"
  type    = "A"
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  ttl     = 300
  records = [aws_lb.video_streaming_lb.dns_name]
}

resource "aws_instance" "video_streaming_server" {
  count         = 3
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.video_streaming_subnet.id
  security_groups = [aws_security_group.video_streaming_sg.name]

  tags = {
    Name = "video-streaming-server-${count.index}"
  }
}
```

This Terraform configuration sets up the infrastructure for a video streaming site with multiple servers to balance load. It includes an AWS VPC, subnet, security group, load balancer, target group, Route53 zone, and Route53 record. The EC2 instances are launched in the subnet and registered with the target group.

