### Description
This Terraform program sets up a VPC with a public subnet and a security group for database access. It then creates a PostgreSQL database instance within the VPC, accessible and secured by the designated security group. The PostgreSQL database instance is configured with a specific version and capacity using the appropriate blueprint and bundle IDs for AWS Lightsail.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "DBSecurityGroup"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBSecurityGroup"
  }
}

resource "aws_lightsail_database" "postgresql_db" {
  relational_database_name = "my-postgresql-db"
  master_database_name     = "postgres"
  master_username          = "admin"
  master_password          = "securepassword123"
  blueprint_id             = "postgres_17_1"
  bundle_id                = "micro_1_0"
  availability_zone        = "us-west-2a"
  publicly_accessible      = true
  apply_immediately        = true

  tags = {
    Name = "PostgreSQLDB"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC with a CIDR block of `10.0.0.0/16` is created.
- **Public Subnet**: A public subnet with a CIDR block of `10.0.1.0/24` is created within the VPC, mapped to the `us-west-2a` availability zone.
- **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL) from any IP address. Outbound traffic is allowed to any IP address.
- **PostgreSQL Database**: A PostgreSQL database instance is created using the `postgres_17_1` blueprint and `micro_1_0` bundle, which corresponds to the required version and capacity. The database is placed in the public subnet and secured by the security group.

