This Terraform program provisions a secure PostgreSQL database instance within a specified AWS VPC. The database instance is configured with the following specifications:
- Engine version: 15
- Storage size: 50GB
- Multi-AZ deployment for high availability
- Encryption using a KMS key
- Custom parameter group for PostgreSQL settings
- Security group to manage access

The program also sets up the necessary AWS resources such as subnets, security groups, and KMS keys.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database will be deployed"
  default     = "vpc-12345678"
}

variable "subnet1_cidr_block" {
  description = "CIDR block for the first subnet"
  default     = "10.0.1.0/24"
}

variable "subnet2_cidr_block" {
  description = "CIDR block for the second subnet"
  default     = "10.0.2.0/24"
}

resource "aws_kms_key" "db_encryption_key" {
  description             = "KMS key for encrypting the PostgreSQL database"
  deletion_window_in_days = 10
}

resource "aws_subnet" "subnet1" {
  vpc_id            = var.vpc_id
  cidr_block        = var.subnet1_cidr_block
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = var.vpc_id
  cidr_block        = var.subnet2_cidr_block
  availability_zone = "us-west-2b"
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
}

resource "aws_security_group" "db_security_group" {
  name        = "postgres-security-group"
  description = "Security group for PostgreSQL database"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Example CIDR block, adjust as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "postgresql_custom_param_group" {
  name   = "custom-postgres-param-group"
  family = "postgres15"

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  parameter {
    name  = "maintenance_work_mem"
    value = "64MB"
  }
}

resource "aws_db_instance" "secure_postgresql_db" {
  engine               = "postgres"
  engine_version       = "15"
  instance_class       = "db.t3.medium"
  allocated_storage    = 50
  multi_az             = true
  username             = "admin"
  password             = "securepassword123"
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  kms_key_id           = aws_kms_key.db_encryption_key.arn
  parameter_group_name = aws_db_parameter_group.postgresql_custom_param_group.name
}
