### Description

This Terraform program provisions a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS services like RDS, subnets, and KMS for encryption. The configuration includes setting up a custom parameter group for PostgreSQL settings, a security group to manage access, and configuring the database instance with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key. Additionally, it creates a snapshot of the database instance with the identifier "pgsnapshot".

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_db_subnet_group" "postgres_subnet_group" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.private.id]
}

resource "aws_kms_key" "db_encryption_key" {
  description             = "KMS key for PostgreSQL database encryption"
  deletion_window_in_days = 10
}

resource "aws_db_parameter_group" "postgres_param_group" {
  name   = "postgres-param-group"
  family = "postgres13"

  parameter {
    name  = "log_connections"
    value = "1"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
  }
}

resource "aws_security_group" "db_security_group" {
  name        = "db-security-group"
  description = "Security group for PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "postgres_db_instance" {
  identifier              = "postgres-db-instance"
  instance_class          = "db.t3.medium"
  engine                  = "postgres"
  engine_version          = "13.7"
  allocated_storage       = 20
  username                = "admin"
  password                = "securepassword"
  db_subnet_group_name    = aws_db_subnet_group.postgres_subnet_group.name
  parameter_group_name    = aws_db_parameter_group.postgres_param_group.name
  vpc_security_group_ids  = [aws_security_group.db_security_group.id]
  multi_az                = true
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.db_encryption_key.arn
  final_snapshot_identifier = "pgsnapshot"

  timeouts {
    create = "30m"
    update = "30m"
    delete = "30m"
  }
}

resource "aws_db_snapshot" "postgres_db_snapshot" {
  db_instance_identifier = aws_db_instance.postgres_db_instance.identifier
  db_snapshot_identifier = "pgsnapshot"
}
```

