### Description

This Terraform program sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "mysql_instance" {
  instance_class       = "db.t3.micro"
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  username             = "admin"
  password             = "password"
  db_name              = "mydatabase"
  publicly_accessible  = true
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
}

output "database_endpoint" {
  value = aws_db_instance.mysql_instance.endpoint
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC**: A main VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnets**: Two subnets are created within the VPC, one in `us-west-2a` and another in `us-west-2b`.
4. **Security Group**: A security group is created to allow inbound traffic on port 3306 (MySQL) from any IP address (`0.0.0.0/0`). Outbound traffic is allowed to any IP address.
5. **DB Subnet Group**: A DB subnet group is created to associate the subnets with the RDS instance.
6. **RDS Instance**: A MySQL RDS instance is created with public accessibility, using the specified subnets and security group. The instance class is `db.t3.micro`, and the storage is set to 20 GB.
7. **Output**: The database endpoint is outputted for connectivity purposes.

