### Description
This Terraform program sets up a PostgreSQL database instance in AWS, including the necessary networking resources such as a VPC and subnet. The database instance is configured with specific details like engine version, instance size, storage, backup retention period, and backup window. Additionally, a backup vault and a backup plan are created to manage backups of the PostgreSQL database instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create a subnet within the VPC
resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a security group for the database instance
resource "aws_security_group" "db_sg" {
  name        = "postgres-db-sg"
  description = "Security group for PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this for security best practices
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.main.id]
}

# Create a PostgreSQL database instance
resource "aws_db_instance" "postgres_db_instance" {
  engine              = "postgres"
  engine_version      = "13.7"
  instance_class      = "db.t3.micro"
  allocated_storage   = 20
  username            = "admin"
  password            = "securepassword"
  db_name             = "mydatabase"
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  db_subnet_group_name = aws_db_subnet_group.main.name
  backup_retention_period = 5
  backup_window         = "03:00-06:00"
}

# Create a backup vault
resource "aws_backup_vault" "backup_vault" {
  name = "postgres-backup-vault"
}

# Create a backup plan
resource "aws_backup_plan" "postgres_backup_plan" {
  name = "postgres-backup-plan"

  rule {
    rule_name         = "daily-backup"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 3 * * ? *)"  # Daily backup at 3 AM UTC
  }
}
```

