### Description
This Terraform program sets up a PostgreSQL database instance in AWS, including the necessary networking resources within a custom VPC and subnet. The database instance is configured to allow major version upgrades, automatically perform minor version upgrades, and is not publicly accessible. Additionally, an IAM role and a security group are created to support a database proxy.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create a subnet
resource "aws_subnet" "db_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a security group for the database instance
resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM role for the DB proxy
resource "aws_iam_role" "db_proxy_role" {
  name = "db-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create a PostgreSQL database instance
resource "aws_db_instance" "postgres_db_instance" {
  instance_class           = "db.t3.micro"
  engine                   = "postgres"
  engine_version           = "13.7"
  allocated_storage        = 20
  allow_major_version_upgrade = true
  auto_minor_version_upgrade = true
  db_name                  = "mydatabase"
  master_username          = "admin"
  master_password          = "securepassword"
  vpc_security_group_ids   = [aws_security_group.db_security_group.id]
  db_subnet_group_name     = aws_db_subnet_group.main.name
  publicly_accessible      = false
}

# Create a DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.db_subnet.id]
}

# Create a DB proxy
resource "aws_db_proxy" "postgres_db_proxy" {
  name                 = "postgres-db-proxy"
  engine_family        = "POSTGRESQL"
  role_arn             = aws_iam_role.db_proxy_role.arn
  vpc_subnet_ids       = [aws_subnet.db_subnet.id]
  vpc_security_group_ids = [aws_security_group.db_security_group.id]

  auth {
    auth_scheme = "SECRETS"
    description = "Proxy authentication"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.my_database_creds.arn
    username    = "admin"
  }
}

# Create a Secrets Manager secret for database credentials
resource "aws_secretsmanager_secret" "my_database_creds" {
  name = "my-database-creds"
}

# Store the database credentials in Secrets Manager
resource "aws_secretsmanager_secret_version" "my_database_creds_version" {
  secret_id     = aws_secretsmanager_secret.my_database_creds.id
  secret_string = jsonencode({
    username = "admin"
    password = "securepassword"
  })
}
```

This Terraform configuration sets up a PostgreSQL database instance in AWS, including the necessary networking resources and an IAM role for a database proxy. The database instance is configured to allow major version upgrades and automatically perform minor version upgrades, and it is not publicly accessible.

