### Description
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the necessary components such as a VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The configuration ensures that all resources are properly interconnected and configured to work together seamlessly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Subnet
resource "aws_subnet" "proxy_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Security Group
resource "aws_security_group" "proxy_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# IAM Role for Proxy
resource "aws_iam_role" "proxy_role" {
  name = "aurora-mysql-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Aurora MySQL Cluster
resource "aws_rds_cluster" "aurora_mysql_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.02.0"
  cluster_identifier  = "aurora-mysql-cluster"
  master_username     = "admin"
  master_password     = "securepassword123"
  db_subnet_group_name = "aurora-mysql-subnet-group"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
}

# DB Subnet Group
resource "aws_db_subnet_group" "aurora_mysql_subnet_group" {
  name       = "aurora-mysql-subnet-group"
  subnet_ids = [aws_subnet.proxy_subnet.id]
}

# DB Proxy
resource "aws_db_proxy" "aurora_mysql_proxy" {
  name                   = "aurora-mysql-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.proxy_subnet.id]
  vpc_security_group_ids = [aws_security_group.proxy_sg.id]

  auth {
    auth_scheme = "SECRETS"
    description = "Proxy authentication"
    iam_auth    = "DISABLED"
    secret_arn  = "arn:aws:secretsmanager:us-west-2:123456789012:secret:aurora-mysql-secret"
    username    = "admin"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet**: A subnet is created within the VPC with a CIDR block of `10.0.1.0/24` in the `us-west-2a` availability zone.
4. **Security Group**: A security group is created to allow inbound traffic on port 3306 (MySQL) from any IP address and outbound traffic to any IP address.
5. **IAM Role**: An IAM role is created for the Aurora MySQL proxy with a trust policy allowing RDS to assume the role.
6. **Aurora MySQL Cluster**: An Aurora MySQL cluster is created with a specified engine version, master username, and password, and associated with the DB subnet group.
7. **DB Subnet Group**: A DB subnet group is created to associate the subnet with the Aurora MySQL cluster.
8. **DB Proxy**: A DB proxy is created with the specified engine family, IAM role ARN, VPC subnet IDs, and security group IDs. The proxy uses Secrets Manager for secure credential storage.

This configuration ensures that all resources are properly set up and interconnected to meet the requirements specified in the prompt.

