### Description

This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the following components:

1. **VPC**: A Virtual Private Cloud (VPC) to host the RDS cluster and proxy.
2. **Subnets**: Two public subnets within the VPC.
3. **Security Group**: A security group to control inbound and outbound traffic to the RDS cluster and proxy.
4. **IAM Role and Policy**: An IAM role with an attached policy to manage RDS and Secrets Manager.
5. **RDS Aurora MySQL Cluster**: An Aurora MySQL cluster configured with a specified backup retention period and preferred backup window.
6. **RDS Proxy**: A proxy to manage connections to the RDS cluster.
7. **Secrets Manager**: A secret to store the RDS cluster credentials securely.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "rds_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "rds_subnet_public_a" {
  vpc_id            = aws_vpc.rds_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "rds_subnet_public_b" {
  vpc_id            = aws_vpc.rds_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "rds_security_group" {
  vpc_id = aws_vpc.rds_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "rds_iam_policy" {
  name        = "rds-iam-policy"
  description = "Policy for RDS and Secrets Manager access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "rds-db:connect"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_rds_policy_to_role" {
  policy_arn = aws_iam_policy.rds_iam_policy.arn
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_rds_cluster" "aurora_mysql_cluster" {
  engine               = "aurora-mysql"
  engine_version       = "8.0.mysql_aurora.3.02.0"
  cluster_identifier   = "aurora-mysql-cluster"
  master_username      = "admin"
  master_password      = "securepassword123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  iam_database_authentication_enabled = true
  skip_final_snapshot = true
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "aurora-mysql-subnet-group"
  subnet_ids = [aws_subnet.rds_subnet_public_a.id, aws_subnet.rds_subnet_public_b.id]
}

resource "aws_db_proxy" "rds_proxy" {
  name                   = "aurora-mysql-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.rds_iam_role.arn
  vpc_subnet_ids         = [aws_subnet.rds_subnet_public_a.id, aws_subnet.rds_subnet_public_b.id]
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.rds_credentials.arn
    username    = "admin"
  }
}

resource "aws_secretsmanager_secret" "rds_credentials" {
  name = "aurora-mysql-credentials"
}

resource "aws_secretsmanager_secret_version" "rds_credentials_version" {
  secret_id     = aws_secretsmanager_secret.rds_credentials.id
  secret_string = jsonencode({
    username = "admin"
    password = "securepassword123"
  })
}
