### Description
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the necessary components such as a VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The RDS cluster is configured to take a final snapshot with the identifier "snapshot".

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "AuroraVPC"
  }
}

resource "aws_subnet" "proxy_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "ProxySubnet"
  }
}

resource "aws_security_group" "proxy_sg" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "ProxySG"
  }
}

resource "aws_iam_role" "proxy_role" {
  name = "AuroraProxyRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "SecretsManagerAccess"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "secretsmanager:GetSecretValue"
          ]
          Effect = "Allow"
          Resource = "*"
        }
      ]
    })
  }
}

resource "aws_rds_cluster" "aurora_mysql_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.02.0"
  cluster_identifier  = "aurora-mysql-cluster"
  master_username     = "admin"
  master_password     = "securepassword"
  db_subnet_group_name = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids = [aws_security_group.proxy_sg.id]
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  skip_final_snapshot = false
  final_snapshot_identifier = "snapshot"

  timeouts {
    create = "120m"
    update = "60m"
    delete = "60m"
  }
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.proxy_subnet.id]
  tags = {
    Name = "AuroraSubnetGroup"
  }
}

resource "aws_db_proxy" "aurora_mysql_proxy" {
  name                   = "aurora-mysql-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.proxy_subnet.id]
  vpc_security_group_ids = [aws_security_group.proxy_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
    username    = "admin"
  }

  timeouts {
    create = "120m"
    update = "60m"
    delete = "60m"
  }
}

resource "aws_secretsmanager_secret" "aurora_credentials" {
  name = "aurora-credentials"
}

resource "aws_secretsmanager_secret_version" "aurora_credentials_version" {
  secret_id     = aws_secretsmanager_secret.aurora_credentials.id
  secret_string = jsonencode({
    username = "admin"
    password = "securepassword"
  })
}
```

This Terraform configuration sets up an Aurora MySQL cluster with a proxy, including necessary VPC, subnet, security group, IAM role, and Secrets Manager setup. The RDS cluster is configured to take a final snapshot with the identifier "snapshot".

