### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_sns_topic" "glacier_sns_topic" {
  name = "glacier-vault-notifications"
}

resource "aws_glacier_vault" "my_glacier_vault" {
