    events   = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
    sns_topic = aws_sns_topic.glacier_sns_topic.arn
  }
}

resource "aws_glacier_vault_lock" "my_glacier_vault_lock" {
  vault_name = aws_glacier_vault.my_glacier_vault.name
  complete_lock = true
  policy = jsonencode({
    PolicyVersion = "2014-03-26",
    Rules = [
      {
        ID          = "string",
        MinimumRetentionDays = 30,
        MaximumRetentionDays = 365
      }
    ]
  })
}
```

