LLM Output #0:
### Description

This Terraform program creates an S3 Glacier vault, sets up an access policy using `aws_iam_policy_document`, and locks the policy using `aws_glacier_vault_lock`. The program also includes an SNS topic for notifications, which the Glacier vault depends on.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_sns_topic" "glacier_sns_topic" {
  name = "glacier-vault-notifications"
}

data "aws_iam_policy_document" "glacier_access_policy" {
  statement {
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "glacier:InitiateJob",
      "glacier:GetJobOutput",
      "glacier:ListJobs",
      "glacier:DescribeVault"
    ]

    resources = ["arn:aws:glacier:*:*:vaults/my-archive"]
  }
}

resource "aws_glacier_vault" "my_archive" {
  name = "my-archive"

  notification {
    sns_topic = aws_sns_topic.glacier_sns_topic.arn
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
  }

  access_policy = data.aws_iam_policy_document.glacier_access_policy.json
}

resource "aws_glacier_vault_lock" "my_archive_lock" {
  vault_name = aws_glacier_vault.my_archive.name
  policy     = jsonencode({
    Policy = {
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Deny"
          Principal = "*"
          Action   = "glacier:DeleteVault"
          Resource = "arn:aws:glacier:*:*:vaults/my-archive"
        }
      ]
    }
  })
  complete_lock = true
}
```

This Terraform configuration sets up an S3 Glacier vault named `my-archive`, configures an SNS topic for notifications, defines an access policy using `aws_iam_policy_document`, and locks the policy using `aws_glacier_vault_lock`. The Glacier vault is configured to send notifications for job completion events to the specified SNS topic.

