### Description
This Terraform configuration sets up an Application Load Balancer (ALB) with two public subnets. It includes an ALB, a target group, and a listener that forwards traffic to the target group. The subnets are assumed to exist within a VPC, and the configuration does not create the VPC itself.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_subnet" "subnet_public_1" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_public_2" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_lb" "application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = aws_subnet.subnet_public_1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet_public_2.id
  }

  security_groups = ["sg-12345678"]  # Replace with your security group ID
}

resource "aws_lb_target_group" "application_target_group" {
  name     = "my-application-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-12345678"  # Replace with your VPC ID

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener" "application_listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.application_target_group.arn
  }
}
```

### Notes
- Replace `"vpc-12345678"` with your actual VPC ID.
- Replace `"sg-12345678"` with your actual security group ID.
- Ensure that the subnets and VPC are properly configured and exist before applying this Terraform configuration.

