### Description
This Terraform program creates an Application Load Balancer (ALB) that forwards traffic to one or more EC2 instances in a target group. The ALB is configured with a security group and operates within a specified subnet. The target group is associated with the ALB, and the necessary security group rules are set to allow HTTP traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "lb_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "lb_security_group" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_target_group" "lb_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb" "lb" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"

  security_groups = [aws_security_group.lb_security_group.id]
  subnet_mapping {
    subnet_id = aws_subnet.lb_subnet.id
  }

  depends_on = [aws_lb_target_group.lb_target_group]
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Subnet**: A subnet is created within the VPC with a CIDR block of `10.0.1.0/24` and placed in the `us-west-2a` availability zone.
- **Security Group**: A security group is created to allow inbound HTTP traffic on port 80 from any IP address. Egress rules allow all outbound traffic.
- **Target Group**: An Application Load Balancer target group is created to forward traffic to instances on port 80 using the HTTP protocol. Health checks are configured to monitor the instances.
- **Load Balancer**: An Application Load Balancer is created, associated with the security group and subnet. It forwards traffic to the target group.

