### Description
This Terraform program creates a Network Load Balancer (NLB) and attaches it to two subnets in different Availability Zones. It also sets up a listener for the NLB. The subnets are created within a VPC, and the NLB is configured to handle TCP traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_lb" "nlb" {
  name               = "my-nlb"
  load_balancer_type = "network"

  subnet_mapping {
    subnet_id = aws_subnet.subnet1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet2.id
  }
}

resource "aws_lb_listener" "nlb_listener" {
  load_balancer_arn = aws_lb.nlb.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = "arn:aws:elasticloadbalancing:us-west-2:123456789012:targetgroup/my-target-group/1234567890123456"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC Creation**: A VPC is created with a CIDR block of `10.0.0.0/16`.
3. **Subnet Creation**: Two subnets are created within the VPC, each in a different Availability Zone (`us-west-2a` and `us-west-2b`).
4. **Network Load Balancer (NLB)**: An NLB is created and attached to the two subnets.
5. **Listener for NLB**: A listener is set up on the NLB to handle TCP traffic on port 80. The `default_action` forwards traffic to a target group, which is represented by a placeholder ARN. You should replace this ARN with the actual ARN of your target group.

