### Description
This Terraform program creates an Application Load Balancer (ALB) with a listener that has a redirect action. The ALB is configured with a subnet mapping and a security group. The listener is set up to redirect HTTP traffic to HTTPS.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  count             = 2
  vpc_id            = aws_vpc.example.id
  cidr_block        = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index)
  availability_zone = element(["us-west-2a", "us-west-2b"], count.index)
}

resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "my_load_balancer" {
  name               = "my-load-balancer"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = aws_subnet.example[0].id
  }

  subnet_mapping {
    subnet_id = aws_subnet.example[1].id
  }

  security_groups = [aws_security_group.example.id]
}

resource "aws_lb_listener" "my_load_balancer_listener" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      protocol         = "HTTPS"
      port             = "443"
      status_code      = "HTTP_301"
    }
  }
}
```

This Terraform configuration sets up an Application Load Balancer with two subnets and a security group that allows HTTP and HTTPS traffic. The listener on port 80 redirects all incoming HTTP traffic to HTTPS on port 443.

