### Description
This Terraform program creates an Application Load Balancer (ALB) with a fixed-response action. The ALB is configured to listen on port 80 and respond with a fixed message to any incoming HTTP requests. The program includes the necessary resources and dependencies, ensuring that the Load Balancer and Listener are correctly set up.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  count             = 2
  vpc_id            = aws_vpc.example.id
  cidr_block        = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index)
  availability_zone = element(["us-west-2a", "us-west-2b"], count.index)
}

resource "aws_lb" "front_end" {
  name               = "example-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.example.id]
  subnets            = aws_subnet.example[*].id
}

resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_listener" "front_end" {
  load_balancer_arn = aws_lb.front_end.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, World!"
      status_code  = "200"
    }
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC and Subnets**: A VPC and two subnets are created to host the Load Balancer.
- **Security Group**: A security group is created to allow HTTP traffic on port 80.
- **Application Load Balancer (ALB)**: An ALB is created with the specified name, type, and subnets.
- **Listener**: A listener is attached to the ALB to listen on port 80 with a fixed-response action that returns a plain text message "Hello, World!" with a status code of 200.

