### Description
The Terraform program below creates an Application Load Balancer (ALB) with a Lambda Target Group. The ALB will route incoming traffic to an AWS Lambda function. The program includes the necessary resources such as the ALB, the Lambda Target Group, and the necessary IAM role for the ALB to invoke the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_invocation_role" {
  name = "lambda-invocation-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_invocation_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_invocation_role.name
}

resource "aws_lb_target_group" "lambda_target_group" {
  name     = "lambda-target-group"
  port     = 443
  protocol = "HTTPS"
  vpc_id   = "vpc-12345678"  # Replace with your VPC ID

  lambda_multi_value_headers_enabled = true
  target_type                        = "lambda"

  health_check {
    enabled             = true
    interval            = 30
    path                = "/health"
    port                = "traffic-port"
    protocol            = "HTTPS"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = "application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  subnets            = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs

  security_groups = ["sg-12345678"]  # Replace with your security group ID

  enable_deletion_protection = false
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-Ext-2018-06"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"  # Replace with your ACM certificate ARN

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda_target_group.arn
  }
}
```

### Notes
- Replace `"vpc-12345678"` with your actual VPC ID.
- Replace `["subnet-12345678", "subnet-87654321"]` with your actual subnet IDs.
- Replace `"sg-12345678"` with your actual security group ID.
- Replace `"arn:aws:acm:us-west-2:123456789012:certificate/12345678-1234-1234-1234-123456789012"` with your actual ACM certificate ARN.
- Ensure that the AWS account has the necessary permissions to create Lambda Target Groups.

