### Description
This Terraform program creates an AWS RDS database instance restored from an S3 bucket. It includes the necessary IAM role with the appropriate permissions to access the S3 bucket and perform the import operation.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "s3_restore_role" {
  name = "s3-restore-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "s3-restore-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Effect = "Allow"
          Resource = [
            "arn:aws:s3:::my-backup-bucket",
            "arn:aws:s3:::my-backup-bucket/*"
          ]
        }
      ]
    })
  }
}

resource "aws_db_instance" "db_instance_from_s3" {
  instance_class = "db.t3.micro"
  engine         = "mysql"
  engine_version = "8.0"
  allocated_storage = 20
  db_name        = "mydatabase"
  username       = "admin"
  password       = "securepassword"

  s3_import {
    bucket_name     = "my-backup-bucket"
    ingestion_role  = aws_iam_role.s3_restore_role.arn
    source_engine   = "mysql"
    source_engine_version = "8.0"
    bucket_prefix   = "backups/"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `s3-restore-role` is created with a trust policy allowing RDS to assume the role. An inline policy grants permissions to get objects and list buckets from the specified S3 bucket (`my-backup-bucket`).
3. **RDS Instance**: An RDS MySQL instance is created with the specified instance class, storage, and database details. The `s3_import` block is used to specify the S3 bucket, IAM role, and other necessary parameters for restoring the database from the S3 backup.

