### Description
This Terraform program creates an AWS EFS (Elastic File System) with associated tags, a VPC, a subnet, and a security group. The EFS file system is mounted using an EFS mount target within the specified subnet and security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "EFS-VPC"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "EFS-Subnet"
  }
}

resource "aws_security_group" "security_group" {
  vpc_id      = aws_vpc.vpc.id
  description = "Allow NFS traffic for EFS"

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "EFS-SecurityGroup"
  }
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"
  performance_mode = "generalPurpose"
  throughput_mode = "bursting"
  tags = {
    Name = "MyEFSFileSystem"
    Environment = "Production"
  }
}

resource "aws_efs_mount_target" "efs_mount_target" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.subnet.id
  security_groups = [aws_security_group.security_group.id]
}
```

This Terraform configuration sets up an EFS file system with the specified tags, along with a VPC, subnet, and security group necessary for mounting the EFS file system. The security group allows NFS traffic on port 2049 from any IP address.

