### Description
This Terraform program creates an AWS Elastic File System (EFS) with a lifecycle policy, along with a mount target in a specified subnet and security group. The EFS file system is configured to automatically transition files to the IA (Infrequent Access) storage class after 30 days of inactivity.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "EFS-VPC"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "EFS-Subnet"
  }
}

resource "aws_security_group" "security_group" {
  vpc_id = aws_vpc.vpc.id
  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "EFS-SG"
  }
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"
  performance_mode = "generalPurpose"
  throughput_mode = "bursting"
  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }
  tags = {
    Name = "MyEFS"
  }
}

resource "aws_efs_file_system_policy" "efs_file_system_policy" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "elasticfilesystem:*"
        Resource = aws_efs_file_system.efs_file_system.arn
      }
    ]
  })
}

resource "aws_efs_mount_target" "efs_mount_target" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.subnet.id
  security_groups = [aws_security_group.security_group.id]
}
```

This Terraform configuration sets up an EFS file system with a lifecycle policy to transition files to IA storage class after 30 days. It also creates a VPC, subnet, and security group to support the EFS mount target. The security group allows inbound traffic on port 2049 for NFS access.

