Below is a complete Terraform HCL program that creates an AWS EFS with automatic backups enabled, along with the necessary dependencies such as a subnet, security group, IAM role, and Lambda function.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "security_group" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"

  lifecycle_policy {
    transition_to_archive = "AFTER_30_DAYS"
  }

  protection {
    replication_overwrite = true
  }
}

resource "aws_efs_mount_target" "efs_mount_target" {
  file_system_id = aws_efs_file_system.efs_file_system.id
  subnet_id      = aws_subnet.subnet.id
  security_groups = [aws_security_group.security_group.id]
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_iam_role_policy_attachment" "lambda_vpc_access" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "my-lambda-code-bucket-${random_string.suffix.result}"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "my-lambda-function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  s3_bucket     = aws_s3_bucket.lambda_code_bucket.bucket
  s3_key        = "function.zip"

  file_system_config {
    arn        = aws_efs_file_system.efs_file_system.arn
    local_mount_path = "/mnt/efs"
  }
}
```

This Terraform configuration sets up an EFS file system with automatic backups enabled, a subnet, a security group, an IAM role for the Lambda function, and the Lambda function itself. The Lambda function is configured to use the EFS file system.

