This Terraform program creates an egress-only internet gateway named "pike" associated with a specified VPC. The VPC is configured to support IPv6, and the egress-only internet gateway is tagged with "permissions". The program ensures that the VPC is properly set up to support IPv6 before associating it with the egress-only internet gateway.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be changed as needed
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  assign_generated_ipv6_cidr_block = true
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_egress_only_internet_gateway" "pike_egress_only_igw" {
  vpc_id = aws_vpc.main_vpc.id
  tags = {
    Name = "pike"
    permissions = "true"
  }
}
```

